class CodeMirrorLintService {
    private rest: RestClient;
    private currentRequest: ThreadingEventWithResult | null;

    constructor(rest: RestClient) {
        this.rest = rest;
        this.currentRequest = null;
    }

    async lint(doc: Document): Promise<any> {
        if (this.currentRequest) {
            this.currentRequest.abort();
        }

        const promise = new ThreadingEventWithResult();
        this.currentRequest = promise;

        try {
            const response = await this.rest.post('/v1/transform/wikitext/to/lint', {
                wikitext: doc.toString(),
                timeout: 30000 // Default timeout of 30 seconds
            });

            promise.setResult(response);
        } catch (error) {
            promise.setException(error);
        } finally {
            this.currentRequest = null;
        }

        return promise.getResultOrThrow();
    }
}

